        [1226415] = "«Перемотування часу» також зменшує всю шкоду, отримувану вашою ціллю, на $1226414s1% протягом $1226414d.",
        [1226423] = "Ваша «Жива бомба» тепер завдає шкоди кожні $s1 с і вибухає, якщо ціль помирає. Крім того, ефект «Зледеніння» від руни «Крижаний спис» тепер накопичується до $s2 разів, а «Стріла крижаночарів» надає $s3 накладання при кожному влучанні.",
        [1226432] = "Зменшує час відновлення «Крижаної сфери» на ${$m4/-1000} с. Щоразу, коли «Зледеніння» поглинається, час відновлення «Глибокого замороження» зменшується на ${$m5/1000}.1 с за кожне поглинуте накладання. Зменшує час відновлення «Вогняного підриву» на ${$m2/-1000} с, а «Вогняний підрив» тепер поновлює тривалість «Живої бомби» на цілі.",
        [1226446] = "Застосування «Глибокого замороження» збільшує залишок тривалості «Крижаних жил» на ${$m1/1000} с. Застосування «Піробласта» скасовує $s2 $lstack:stacks; ефекту від вашої «Стріли згубного вогню».",
        [1226452] = "«Покладання рук» надає вам $1226451s1% швидкості вимовляння заклять на $1226451d і зменшує глобальний час відновлення наступних $1226451n заклять «Божественне світло», «Святе світло», «Спалах Світла» або «Святий шок» на ${$1226451m2/-1000}.1 с.",
        [1226454] = "Ваш «Маяк Світла» тепер також спрацьовує, коли ви зцілюєте ціль «Маяка Світла», але з ефективністю, зменшеною на $s1%.",
        [1226459] = "Додаткові $s1% вашого зцілення переносяться на ціль «Маяка Світла».",
        [1226460] = "Поки ви використовуєте дворучну зброю, «Удар хрестоносця» та «Екзорцизм» надають вам силу святості, збільшуючи всю завдану вами шкоду від святості на $1226461s1%; ефект накопичується до $1226461u разів.",
        [1226462] = "«Божественна буря», «Святий шок» і «Святий гнів» поглинають усю вашу силу святості, завдаючи на $s1% більше шкоди за кожну накопичену одиницю сили святості; проти цілей під контролем гравців ефективність становить $s2%.",
        [1226463] = "Поглинання сили святості збільшує вашу силу атаки на $1226464s1% за кожну поглинуту одиницю протягом $1226464d.",
        [1226467] = "«Щит праведності» також збільшує величину блокування на $1226466s1% протягом $1226466d.",
        [1226477] = "«Щит праведності» завдає додаткової шкоди у відсотках, що дорівнює вашій імовірності блокування.",
        [1226479] = "Ваш «Гнів месника» більше не спричиняє «Стриманість», триває на ${$m1/1000} с довше та збільшує величину блокування на $1233525s1%.",
        [1226499] = "Зменшує час відновлення «Слова сили: Бар’єр» на ${$m2/-1000} с, а «Сплеск Світла» тепер також робить «Молитву зцілення» та «Велике зцілення» миттєвими.",
        [1226501] = "Збільшує зцілення від «Кола зцілення» та «Покаяння» на $s3%. Крім того, час відновлення «Духа Спасителя» зменшується на ${$m1/-1000} с, а ваше зцілення збільшується на $s2%, поки «Дух Спасителя» активний.",
        [1226565] = "Застосування «Слова сили: Щит» миттєво зцілює ціль на $s1% від величини поглинання, а зцілення заклять, посилених «Щасливим випадком», збільшується на $s2% за кожне накладання.",
        [1226585] = "Ваші «Катування розуму» та «Випалювання розуму» більше не втрачають тривалості від отримання шкоди під час підтримання. Крім того, вони завдають на $s2% більше шкоди за кожен інший ваш періодичний ефект тіньової шкоди на цілі, до максимуму ${$m2*3}%.",
        [1226591] = "Ваш «Вибух розуму» створює на $s1% менше загрози та отримує $s2% бонусу до шкоди за кожне накладання «Шипа розуму» на цілі.",
        [1226595] = "Шкода вашого «Катування розуму» зростає що довше ви підтримуєте закляття. Щоразу, коли воно завдає шкоди, наступна шкода збільшується на $s1%. Ефект скидається з кожним новим підтриманням.",
        [1226814] = "Відновлює $25695o1 здоров’я та $25696o2 мани протягом $25695d. $?s446847[Tastes even better inside of Naxxramas, restoring $1226808o1% health and $1226808o2% mana over $1226808d instead.][] Під час їжі потрібно залишатися сидячи.",
        [1226843] = "Поки «Лише тілесна рана» не активна, ваші «Удар у спину», «Підступний удар», «Шабельний розтин» і «Калічення» завдають на $s1% більше шкоди за кожен ваш активний ефект отрути або кровотечі на цілі, максимум до $m2%.",
        [1226869] = "Ваші критичні удари отрутою та автоматичними атаками мають $h% шанс надати вам очко серії.",
        [1226871] = "Збільшує шкоду «Засідки», «Потрошіння», «Багряної бурі» та «Отруєння» на $s1%.",
        [1226874] = "Ваші накладання «Тримати удар» також збільшують усю завдану вами шкоду на $1234069s1%.",
        [1226882] = "Ваш «Шквал клинків» тепер також уражає третю ціль і додатково збільшує швидкість атаки на $s1%. Крім того, кожне витрачене очко серії зменшує залишок часу відновлення «Шквалу клинків» на ${$m2/1000}.1 с.",
        [1226956] = "Ваше «Тримати удар» тепер надає на $s2% більше здоров’я та на $s1% більше шкоди за кожне накладання. При $s3 накладаннях щоразу, коли ви ухиляєтеся або парируєте, ви отримуєте $1226957s3 енергії. ",
        [1226961] = "Коли ваше «Виверження лави», «Ланцюгова блискавка» або «Блискавка» вражає ціль під дією вашого «Вогняного шоку» 5-го або 6-го рангу, воно також завдає один такт шкоди «Вогняного шоку».",
        [1226977] = "Ймовірність спрацювання «Перевантаження» додатково збільшується на $s1%, а шкода «Виверження лави» збільшується на відсоток, що дорівнює вашій ймовірності критичного удару закляттями. Коли «Блискавка» або «Ланцюгова блискавка» завдає шкоди, шкода наступного «Виверження лави», застосованого протягом $1233835d, збільшується на $1233835s1%, накопичуючись до $1233835u разів.",
        [1226978] = "Коли ваша «Ланцюгова блискавка» уражає менше ніж $s1 цілей, вона завдає на $s2% більше шкоди за кожну відсутню до $s1 ціль.",
        [1226981] = "Шкода, завдана вами або вашим прикликаним демоном, має $426301h% шанс збільшити шкоду іншого на $426303s1% протягом $426303d. ",
        [1226984] = "Поки «Статичний шок» активний, «Лавовий батіг», «Виверження лави» та «Удар бурі» мають $h% шанс додати заряд до вашого «Щита блискавки». Якщо кількість зарядів перевищує $s1, «Щит блискавки» негайно завдасть шкоди вашій цілі замість додавання заряду.",
        [1226986] = "Зменшує час відновлення «Тотема вогняної нови» на $s1%, збільшує його шкоду на $s4% і зменшує витрати мани на $s5%. Крім того, «Тотем вогняної нови» тепер активується миттєво після застосування.",
        [1226997] = "«Зброя Виру» тепер може накопичувати до ${$m1+5} зарядів. Під час використання дворучної зброї ви отримуєте по $s4 заряди за раз. Застосування заклять із понад $s1 зарядами збільшує шкоду або зцілення такого закляття на $s2% за кожен надлишковий заряд. Застосування закляття при ${$m1+5} зарядах поглинає всі заряди й застосовує його двічі.",
        [1227019] = "Поєднайте три квітки, торкнуті Скверною, у зілля, яке тимчасово покаже демонічні тіні.",
        [1227022] = "Дозволяє користувачеві тимчасово бачити демонічні тіні у Скверноліссі.",
        [1227080] = "Навчає готувати найжаданіші рецепти бенкетів Керрі Вогнищесердної.",
        [1227088] = "Зменшує час вимовляння вашої наступної «Малої хвилі зцілення», «Хвилі зцілення» або «Ланцюгового зцілення» на $s1%.",
        [1227093] = "Зцілення від вашого «Земного щита» мають $s1% шанс зробити ваше наступне зцілювальне закляття з часом вимовляння миттєвим.",
        [1227099] = "Ваші «Хвиля зцілення» та «Мала хвиля зцілення» також зцілюють ціль вашого «Земного щита» на $s1% від цієї величини, якщо це інша ціль.",
        [1227111] = "Ваше «Ланцюгове зцілення» перескакує ще на $s1 цілей, а його ефективність зменшується на $s2% менше з кожним стрибком.",
        [1227153] = "Ваші закляття шоку активують здібність руни «Майстерність щита», а ефект «Майстерності щита» тепер може накопичуватися до $s1 разів.",
        [1227159] = "Щоразу, коли ваш «Щит блискавки» завдає шкоди, ви зцілюєтеся на $s1% від завданої ним шкоди, але не частіше ніж раз на $s2 с.",
        [1227164] = "Накладання «Майстерності щита» також зменшують час вимовляння «Виверження лави» на $s1% за кожне накладання. «Виверження лави» більше не поглинає заряди «Зброї Виру».",
        [1227175] = "Ваші неперіодичні критичні удари тінню та вогнем змушують ціль горіти, завдаючи $s1% від завданої ними шкоди протягом $1227177d.",
        [1227186] = "Ваші «Тіньова стріла», «Переслідування», «Стріла хаосу», «Тіньове розсічення» та «Вогонь душі» завдають на $s1% більше шкоди цілям, ураженим вашим «Псуванням».",
        [1227196] = "Ваші періодичні критичні удари надають $1227200s1% швидкості вимовляння заклять на $1227200d, а «Зворотна тяга» додатково надає $s2% швидкості вимовляння заклять.",
        [1227204] = "Ви зцілюєтеся на $s1% від усієї шкоди, завданої вашим «Псуванням». Це зцілення збільшується до $s2%, якщо ціль також уражена вашим «Висмоктуванням життя».",
        [1227214] = "Ваше «Тіньове розсічення» тепер накладає «Псування» 7-го рангу на кожну вражену ціль, але його тривалість становить лише $1223963d.",
        [1227228] = "Ваш «Інфернальний обладунок» тепер також збільшує всю завдану вами магічну шкоду на $440882s1% і триває на ${$m1/1000} с довше.",
        [1227231] = "Шкода ваших «Героїчного удару», «Розсічення» та «Швидкого удару» збільшується на $s2% у бойовій стійці або стійці берсерка. «Розсічення» вражає ще $s1 ціль і може спричинити «Сплеск крові».",
        [1227232] = "Щоразу, коли ви вражаєте ціль «Вихором», «Героїчним ударом», «Швидким ударом» або «Розсіченням», шкода вашого наступного «Потужного удару» збільшується на $1234005s1%, накопичуючись до $1234005u разів.",
        [1227234] = "Щоразу, коли «Глибокі рани» завдають шкоди, вони зменшують залишок часу відновлення «Вихору» на $s1 с. «Вихор» завдає на $s2% більше шкоди цілям, ураженим вашими «Глибокими ранами».",
        [1227237] = "Ваша «Ударна хвиля» завдає на $s1% більше шкоди, а її час відновлення зменшується на ${$m2/1000}.1 с щоразу, коли ви вражаєте ціль «Героїчним ударом» або «Розсіченням».",
        [1227242] = "Ваші здібності «Безрозсудність», «Відплата» та «Стіна щитів» більше не мають спільного часу відновлення. Крім того, «Безрозсудність» триває на ${$m1/1000} с довше, а поки вона активна, ви отримуєте силу в розмірі $s2% вашої навички захисту понад 300. ",
        [1227245] = "Ваші здібності більше не мають вимог до стійки. Крім того, влучання «Помстою», «Спустошенням» або «Ударом щитом» збільшують шкоду наступного «Вихору» або «Страти» на $1234067s3%, накопичуючись до $1234067u разів.",
