        [1230086] = "Погрожує закувати ціль у колодки, змушуючи її тікати від страху протягом $d.",
        [1230099] = "Завдає $s1% шкоди зброєю ворогам перед заклиначем і накладає «Пекучу рану» на основну ціль заклинача.\r\n",
        [1230102] = "Завдає $1230099s1 шкоди кожні $1230102t1 с протягом $1230102d. Накопичується.",
        [1230105] = "Закликає міць дикої природи, створюючи розломи, що вибухають і завдають шкоди ворогам поблизу перед заклиначем",
        [1230106] = "Завдає шкоди ворогам у зоні вибуху.",
        [1230117] = "Створіть набір першої допомоги.",
        [1230123] = "Завдає ворогам у зоні вибуху $s1 шкоди від сил природи.",
        [1230161] = "Створіть магнітний камінь.",
        [1230171] = "Створіть точильний круг.",
        [1230200] = "Завдає ворогові $s2 шкоди від сил природи та збільшує отримувану ним шкоду від сил природи на $s1% протягом $d.\r\n",
        [1230203] = "Завдає цілі $s1 шкоди від святості та збільшує завдавану нею шкоду на $s2%.",
        [1230206] = "Гасить внутрішнє полум’я цілі, завдаючи $s1% її максимального здоров’я як шкоду від святості за кожне накладання «Розпалити святе полум’я». Ті, хто виживе, страждатимуть.",
        [1230215] = "Карає ворога на $s1 шкоди від святості. Зцілює вас на $s2% від завданої шкоди.",
        [1230224] = "Розкриває ваш потенціал у Наксрамасі.  Збільшує завдану вами шкоду на ${$m1/100}.2%, а запас здоров’я — на ${$m2/100}.2% за кожен екіпірований предмет Освяченого обладунку.",
        [1230228] = "Зцілює ворога на $s1% його максимального здоров’я, однак він отримуватиме $s2% максимального здоров’я як шкоду кожні $t2 с, доки не вийде з бою.",
        [1230242] = "Завдає ворогові $s2 шкоди від вогню та збільшує отримувану ним шкоду від вогню на $s1% протягом $d.\r\n",
        [1230255] = "Випускає магічно насичений постріл, що обплутує ворогів у невеликій області.",
        [1230319] = "Смерть супутника пробуджує сплеск енергії, збільшуючи завдану шкоду на $s1% і швидкість атаки на $s3%.\r\n",
        [1230438] = "Стріляє у ворога, завдаючи шкоди від святості.",
        [1230538] = "Спробуйте зв’язатися з безтілесним голосом Попелителя.",
        [1230564] = "Створіть криницю мани.",
        [1230583] = "Ненадовго виявляє та перевантажує ваш прототип магніту, намагаючись упіймати розкидані металеві предмети.",
        [1230613] = "Кидає пастку, що вкриває полум’ям того, хто її активує, завдаючи шкоди від вогню та збільшуючи отримувану ним шкоду.\r\n",
        [1230633] = "Викликає виверження магми, що завдають шкоди ворогам поблизу.\r\n",
        [1230637] = "Завдає ворогам у зоні вибуху $s1 шкоди від вогню.\r\n",
        [1230638] = "Завдає шкоди ворогам у зоні вибуху.\r\n",
        [1230643] = "Створіть зачаровану лютню.",
        [1230656] = "Створіть робота-реагентника.",
        [1230671] = "Поєднайте емблему Попелителя, перекований клинок Попелителя та руків’я Попелителя. ",
        [1230897] = "Максимальний запас здоров’я зменшено на $S1%.",
        [1230899] = "Кидає пастку, що вкриває полум’ям того, хто її активує, завдаючи шкоди від вогню та збільшуючи отримувану ним шкоду.\r\n",
        [1230942] = "Збільшує максимальний запас здоров’я на $s1 протягом $d.",
        [1230948] = "Глобальний час відновлення ваших наступальних заклять зменшується на ${$m1/-1000}.1 с.",
        [1230980] = "Встановлює штандарт Стілтза, збільшуючи максимальний запас здоров’я всіх союзників поблизу на $1231903s1 протягом $d.",
        [1230990] = "Насичена зброя тепер змушує атаки ближнього бою завдавати додатково $1230996s1 шкоди від вогню.",
        [1230992] = "Вас охоплює нудота. Повертайте назад!",
        [1230996] = "Завдає $s1 шкоди від вогню та ще $s2 шкоди від вогню кожні $t2 с протягом $d.\r\n",
        [1231010] = "Вішас позначає ворожих гравців. Коли позначена ціль застосовує закляття, Вішас кидає ніж у її напрямку.",
        [1231011] = "Вішас кидає один зі своїх кинджалів у ворога, завдаючи $s2 шкоди від тіні першому враженому ворогові. Якщо ніж влучає в гравця під дією «Болісної догани», він також спричиняє кровотечу.",
        [1231024] = "Спробуйте самі скористатися Портіпортером, щоб зрозуміти, через що стільки галасу.\r\n\r\nМожна використовувати лише в Новому Авалоні та після перевірки відносної безпеки на інших піддослідних.",
        [1231085] = "Випускає магічно насичений постріл, що обплутує ворогів у невеликій області.",
        [1231095] = "Атакує розум цілі, завдаючи $s1 шкоди від тіні та збільшуючи отримувану нею шкоду від тіні на $s2 протягом $d.\r\n",
        [1231123] = "Прикликає Пепе, щоб він приєднався до ваших пригод!",
        [1231124] = "Зцілює вас на $s2 і збільшує силу на $s1 протягом $d.",
        [1231128] = "Назавжди зачаровує зброю ближнього бою так, що під час атак у ближньому бою вона часто зцілює на $1231124s2 і збільшує силу на $1231124s1 протягом $1231124d.",
        [1231138] = "Відновлює $s2 мани та збільшує силу заклять на $s1 протягом $d.",
        [1231139] = "Назавжди зачаровує дворучну зброю ближнього бою так, що під час влучання закляттям вона часто відновлює $1231138s2 мани та збільшує силу заклять на $1231138s1 протягом $1231138d.",
        [1231162] = "Відновлює $s2 мани та збільшує силу заклять на $s1 протягом $d.",
        [1231164] = "Назавжди зачаровує зброю ближнього бою так, що під час влучання закляттям вона часто відновлює $1231162s2 мани та збільшує силу заклять на $1231162s1 протягом $1231162d.",
        [1231212] = "Ось-ось вибухне у славетному прояві магічної майстерності, перетворюючи вас і всіх союзників поблизу.",
        [1231245] = "\r\n\r\n",
        [1231247] = "Кісткоік випльовує некротичну слину, завдаючи $333489s1 шкоди від тіні кожні $333489t с. ворогам, що потрапили під подих, і зменшуючи отримуване ними зцілення на $333489s3%.\r\n\r\n",
        [1231254] = "Збільшує захист на $s1 і броню на $s2 протягом $d.",
        [1231258] = "Атаки ближнього бою мають шанс заразити ворога гниллю, що завдає $1231261s1 шкоди від сил природи кожні $1231261t1 с усім ворогам у радіусі $1231261a1 ярдів від заклинача протягом $1231261d. Швидкість атаки цих цілей також сповільнюється на $1231261s2%.",
        [1231267] = "Звичайна дальня атака по цілі готує вас до бою, збільшуючи захист на $1231266s1 і швидкість атак ближнього бою на $1231266s2% протягом $1231266d.",
        [1231272] = "Кидає в ціль зіпсовану їжу, завдаючи фізичної шкоди.",
        [1231280] = "Приковує ворога до землі на $d і завдає $s1% його максимального здоров’я кожні $t1 с.",
        [1231282] = "У Залі Оновлення створюється калюжа лави, що затоплює нижній рівень.",
        [1231284] = "Б’є ціль гнилим фруктом у руці, перериваючи вимовляння її закляття.",
        [1231289] = "Закликає Волю Гори, збільшуючи завдану фізичну шкоду на $s1%, броню на $s2 і розмір на $s3% протягом $d.",
        [1231293] = "Розмахує смолоскипом перед собою, завдаючи $s1 шкоди від вогню до $x1 цілей.\r\n\r\nВражені цілі загоряються.",
        [1231297] = "Кидає смолоскип у ворога, завдаючи $s1 шкоди від вогню.\r\n\r\nПідпалює його.",
        [1231301] = "Отримує $s1% шкоди від вогню кожні $t1 с протягом $d. Накопичується до $U разів.\r\n\r\nСпричиняється здібностями вартових Нового Авалону, коли вони використовують свої смолоскипи.",
        [1231310] = "Позначає ціль як порушника, не дозволяючи їй використовувати непомітність, невидимість і накладати маскування протягом $d.",
        [1231317] = "Завдає $s1% максимального здоров’я цілі як фізичну шкоду та ще $s2% кожні $t2 с протягом $d.\r\n\r\nПісля завершення рана має шанс, що залежить від поточного здоров’я цілі, перетворитися на сказ.",
        [1231324] = "Швидкість руху зменшена на $s1%. Ви отримуєте $s2% максимального здоров’я як фізичну шкоду кожні $t2 с протягом $d.\r\n\r\nБез лікування ви помрете.",
        [1231330] = "Викрадає $s1 життя в до $x ворогів, надаючи $1231339s2 сили або спритності за кожного висмоктаного ворога, накопичуючись до $1231339u разів.",
        [1231339] = "Силу збільшено\r\n на $s1 протягом $d.",
        [1231342] = "Тіні Бальназзара вражають гравців, які не перебувають у межах $1231342A1 ярдів від іншого гравця, завдаючи $1231645s1 шкоди від тіні.",
        [1231343] = "Тіні Бальназзара вражають гравців, які не перебувають у межах $1231342A1 ярдів від іншого гравця, завдаючи $1231645s1 шкоди від тіні.",
        [1231380] = "Якщо ви залишаєтеся в образі кота протягом $1231381t с, відновлення енергії збільшується на $1231381s1%.",
        [1231382] = "Перебування в образі кота протягом $1231381t с збільшує відновлення енергії на $1231381s1%.",
        [1231397] = "Завдає ворогові $s1 фізичної шкоди та зменшує його швидкість руху на $s2% протягом $d.",
        [1231399] = "Завдає $s1 шкоди від тіні та збільшує отримувану ціллю критичну шкоду на $s2% за кожне накладання, до $U разів.",
        [1231400] = "Телепортує ціль до ратуші Нового Авалону та завдає їй $s1% максимального здоров’я як шкоду від тіні.",
        [1231401] = "Підкуповує ціль, гарантуючи вашу особисту безпеку.",
        [1231404] = "Удар по ворогові вищого рівня накладає «Переворот», збільшуючи отримувану ним шкоду від вашої наступної «Страти» на $1231416s1% або «Отруєння» на $1231424s1% за кожне накладання. При $1231416u накладаннях «Страту» можна застосовувати незалежно від запасу здоров’я цілі.",
        [1231406] = "Спритність збільшено на $s1 протягом $d.",
        [1231417] = "$?s446658[Striking a higher level enemy applies a stack of Coup, increasing their damage taken from your next Execute by $1231416s1% per stack, stacking up to $1231416u times. At $1231416u stacks, Execute may be cast regardless of the target's health.]?s21184[Striking a higher level enemy applies a stack of Coup, increasing their damage taken from your next Envenom by $1231424s1% per stack, stacking up to $1231424u times.]?s446374[Striking a higher level enemy applies a stack of Coup, increasing their damage taken from your next Kill Shot by $1231765s1% per stack, stacking up to $1231765u times.][The blade does not respond to your presence.]",
        [1231431] = "Кидає яблуко, завдаючи $s1 фізичної шкоди та приголомшуючи ціль на $d.",
        [1231433] = "Притягує до вас ворога, що відступає.",
        [1231434] = "Притягує до вас ворога, що відступає.",
        [1231435] = "Притягує до вас ворога, що відступає.",
        [1231444] = "З’їдає смачне, щойно зірване яблуко, миттєво відновлюючи $s1% максимального здоров’я та ще $s2% кожні $t2 с протягом $d.",
        [1231488] = "Витягує ворога з недосяжного місця.",
        [1231489] = "Витягує ворога з недосяжного місця.",
        [1231490] = "Витягує ворога з недосяжного місця.",
        [1231492] = "Завершальні прийоми, що завдають шкоди, мають $b1% шанс за кожне очко серії відновити $1231491s1 енергії.",
        [1231502] = "Відкидає всіх ворожих гравців у конусі. Вороги, яких не вдалося відкинути, приголомшуються на $1232842d.",
        [1231507] = "Звичайні атаки ближнього бою накладають на ворожих гравців «Спрагу Віс’ери».",
        [1231509] = "Ганьбить ціль за її зізнання, зменшуючи швидкість руху на $s1%.",
        [1231511] = "Викриває гріхи цілі, руйнуючи частину її незаконно здобутого маскування.",
        [1231541] = "Накопичує силу Віс’ери протягом 1,5 с, а потім вивільняє «Міць Віс’ери», відкидаючи всіх ворожих гравців у конусі перед вами.",
        [1231547] = "Ви атакуєте всіх ворогів поблизу протягом $d, завдаючи шкоди зброєю плюс додатково $1231546s1 кожні $t1 с.",
        [1231548] = "Збільшує силу власника на $s1 протягом $d.",
        [1231549] = "Завдає цілі додатково $s1 шкоди від святості.",
        [1231550] = "Додає $1231549s1 шкоди від святості до ваших атак ближнього бою.",
        [1231551] = "Збільшує силу власника на $s1 протягом $d.",
        [1231553] = "$h% шанс під час влучання в ближньому бою отримати $s1 додаткову атаку.",
        [1231554] = "$h% шанс під час влучання в ближньому бою отримати $s1 додаткову атаку.",
        [1231556] = "Додаткові атаки від «Дволикості й омани» тепер спричиняють $s1 додаткову атаку.",
        [1231559] = "Додаткові атаки від «Дволикості й омани» тепер спричиняють $s1 додаткову атаку.",
        [1231560] = "Додаткові атаки від «Дволикості й омани» тепер спричиняють $s1 додаткову атаку.",
        [1231578] = "Миттєво відновлює $s1 здоров’я, але з часом ви також отримуєте шкоду в розмірі $s2% від цієї величини.\r\n\r\nСимптоми цього ефекту можуть проявитися як отрута тривалістю $1231579d або хвороба тривалістю $1231580d.",
        [1231586] = "«Зосереджений вогонь» тепер надає вам і вашому вихованцеві $1231591s1% додаткової шкоди за кожне поглинуте накладання протягом $1231591d.",
        [1231588] = "Використайте прадавнє полум’я, створене з гілок Нордрассілу, щоб нагріти клинок. ",
        [1231589] = "Загартуйте нагрітий клинок у водах Криниці Вічності.",
        [1231590] = "Збільшує завдану вихованцем шкоду на $w1% протягом $d.",
        [1231591] = "Збільшує завдану шкоду на $w1% протягом $d.",
        [1231592] = "Уражає ціль прокляттям океану. Якщо прокляття не буде розвіяно, ціль потоне.",
        [1231594] = "Ви тонете, відчуваючи поклик мілководдя.",
        [1231595] = "$h% шанс під час дальньої атаки створити Нитку Долі, що дозволяє вам рухатися й одночасно використовувати дальню атаку. Нитки накопичуються до $1231601u разів і тривають $1231601d.",
        [1231605] = "Перетворює вас на Багряну гармату на $d, через що ваші дальні атаки вибухають, завдаючи $1231607s1 шкоди від вогню всім ворогам у межах $1231607a1 ярдів від вашої цілі.",
        [1231614] = "Ваша наступна атака ближнього бою протягом $d завдає шкоди від таємної магії залежно від сили заклять і присипляє ціль на $d.",
        [1231618] = "Завдає $s1% шкоди зброєю та підпалює ціль, завдаючи шкоди сяйвом протягом $d.",
        [1231620] = "Завдання періодичної шкоди має $h% шанс надати $1231623s1 шкоди заклять і зцілення на $1231623d.",
        [1231624] = "Завдання неперіодичної шкоди від вогню має $h% шанс збільшити завдану вами шкоду від вогню на $1231625s1% протягом $1231625d1.",
        [1231628] = "Закляття, що завдає шкоди, має шанс створити над ціллю Міраж, який завдає шкоди від таємної магії ворогам поблизу протягом $1231629d.",
