        [1240367] = "Дозволяє тестовому реміснику виготовляти базові пристрої з максимальною потенційною навичкою 225.  Потрібні інгредієнти, матеріали, а іноді навіть реагенти! [DNT]",
        [1240368] = "Дозволяє тестовому реміснику виготовляти базові пристрої з максимальною потенційною навичкою 300.  Потрібні інгредієнти, матеріали, а іноді навіть реагенти! [DNT]",
        [1240375] = "Професія",
        [1240571] = "Поки «Шок і трепет» активний, «Удар хрестоносця» та «Екзорцизм» надають вам силу святості, збільшуючи всю завдану вами шкоду від святості на $1226461s1%; ефект накопичується до $1226461u разів.",
        [1240573] = "Поглинання сили святості збільшує вашу силу заклять на $1240574s1% за кожну поглинуту одиницю протягом $1240574d.",
        [1240686] = "Збільшує час між атаками ворогів поблизу на $s1% і сповільнює їхню швидкість руху та вимовляння заклять на $s2% протягом $d.",
        [1240688] = "Обплутує ворогів поблизу корінням, завдаючи шкоди від сил природи кожні $t2 с і знерухомлюючи їх на час до $d.",
        [1240692] = "Прадавній Скверни спрямовує отруйні лози до ворога, завдаючи $1240706s1 шкоди від сил природи ворогам у межах 5 ярдів і створюючи на місці отруйні випари, що завдають $1263985s1 шкоди від сил природи кожні $1263985t1 с протягом $1240707d.",
        [1240706] = "Прадавній Скверни спрямовує отруйні лози до ворога, завдаючи $1240706s1 шкоди від сил природи ворогам у межах 5 ярдів і створюючи на місці отруйні випари, що завдають $1263985s1 шкоди від сил природи кожні $1263985t1 с протягом $1240707d.",
        [1240707] = "Прадавній Скверни спрямовує отруйні лози до ворога, завдаючи $1240706s1 шкоди від сил природи ворогам у межах 5 ярдів і створюючи на місці отруйні випари, що завдають $1263985s1 шкоди від сил природи кожні $1263985t1 с протягом $1240707d.",
        [1240720] = "Випускає в ціль залп святого світла, завдаючи $1240727s1 шкоди від святості ворогові або зцілюючи союзника на $1240723s1 миттєво й кожні $402261t2 с протягом $402261d.",
        [1240721] = "Випускає в ціль залп святого світла, завдаючи $1240730s1 шкоди від святості ворогові або зцілюючи союзника на $1240724s1 миттєво й кожні $402261t2 с протягом $402261d.",
        [1240723] = "Зцілює на $s1 кожні $1240732t2 с протягом $1240732d.",
        [1240724] = "Зцілює на $s1 кожні $1240733t2 с протягом $1240733d.",
        [1240727] = "Завдає $s1 шкоди від святості кожні $1240734t2 с.",
        [1240730] = "Завдає $s1 шкоди від святості кожні $1240736t2 с.",
        [1240738] = "Висмоктує життєву силу цілі, завдаючи $s1 шкоди від таємної магії та ще $o2 шкоди від таємної магії протягом $d.",
        [1240750] = "Вражає ворога стрілою висмоктувальної таємної сили, що поглинає до $s1 мани.",
        [1240830] = "Висмоктування таємної сили.",
        [1240869] = "Перетворює ворога на тварину, змушуючи його блукати до $d. Під час блукання перетворена ціль не може атакувати чи застосовувати закляття.",
        [1240921] = "Вивільняє нестабільну ману в області, спрямованій на гравця, завдаючи $s1 шкоди від таємної магії.",
        [1241329] = "Сталася несправність. Кожні $t1s вивільняється таємна енергія, завдаючи шкоди гравцям у зоні поблизу.",
        [1241359] = "Вивільняє конус таємної енергії перед собою, завдаючи $s1 шкоди від таємної магії та відкидаючи всі вражені цілі.",
        [1241501] = "Спрямовує енергію вперед, завдаючи шкоди всім цілям, що потрапили під вибух.",
        [1241506] = "Завдає ворогові $s1 шкоди від таємної магії.",
        [1241515] = "Випускає насичену маною сферу в напрямку випадкового гравця; сфера летить уперед і повертається до місця походження. Вражені гравці отримують $s1 шкоди від таємної магії.",
        [1241523] = "Випускає насичену маною сферу в напрямку випадкового гравця; сфера летить уперед і повертається до місця походження. Вражені гравці отримують $s1 шкоди від таємної магії.",
        [1241524] = "Випускає насичену маною сферу в напрямку випадкового гравця; сфера летить уперед і повертається до місця походження. Вражені гравці отримують $s1 шкоди від таємної магії.",
        [1241582] = "Миттєво атакує обома зброями, завдаючи кожною $1241585s2% шкоди зброєю плюс додатково ${$1241585m1*$1241585m2/100}. Шкода по отруєних цілях збільшується на $m4%. Дає $m1 $LPoint:Points; серії.",
        [1241584] = "Миттєво атакує обома зброями, завдаючи кожною $1241586s2% шкоди зброєю плюс додатково ${$1241586m1*$1241586m2/100}. Шкода по отруєних цілях збільшується на $m4%. Дає $m1 $LPoint:Points; серії.",
        [1241797] = "Ваші завершальні прийоми, що завдають шкоди, зменшують залишок часу відновлення «Викиду адреналіну», «Шквалу клинків», «Ухилення», «Спринту» та «Зникнення» на $m1 с за кожне очко серії.",
        [1241821] = "Запакуйте $M1 руди на ваш вибір.",
        [1242393] = "Прикликає орла-супутника, який супроводжує заклинача, доки його не відкличуть.",
        [1242436] = "Повертає невмерлих прислужників до життя, щоб вони допомагали заклиначеві в бою. ",
        [1242512] = "Відновлює ману під час вимовляння заклять.",
        [1242871] = "Завдає $s1 шкоди від вогню, а потім продовжує завдавати невеликої шкоди від сонячної магії кожні $t2 с.",
        [1242907] = "Завдає поточній ворожій цілі $S1% фізичної шкоди.",
        [1242913] = "Завдає помірної шкоди від сонячної магії, а потім продовжує завдавати невеликої шкоди від сонячної магії кожні $t2 с.",
        [1242971] = "Енергія тіні повільно руйнує ціль, завдаючи $o1 шкоди протягом $d. Крім того, якщо «Нестабільну недугу» розвіють, вона завдасть розвіювачу ${$m1*$m3/100} шкоди та накладе мовчанку на $427719d. На одній цілі від одного чорнокнижника може діяти лише одна «Нестабільна недуга» або «Жертовний вогонь».",
        [1242972] = "Енергія тіні повільно руйнує ціль, завдаючи $o1 шкоди протягом $d. Крім того, якщо «Нестабільну недугу» розвіють, вона завдасть розвіювачу ${$m1*$m3/100} шкоди та накладе мовчанку на $427719d. На одній цілі від одного чорнокнижника може діяти лише одна «Нестабільна недуга» або «Жертовний вогонь».",
