        [1243090] = "$@spelldesc<1243081>\r\n",
        [1243229] = "Завдає поточній ворожій цілі $S1 шкоди від тіні.",
        [1243312] = "$@spelldesc<1243318>",
        [1243318] = "Прикликає біса.",
        [1243339] = "Уражає ціль на $1225228d, змушуючи $1225228s1% усієї шкоди, яку чорнокнижник завдає іншим цілям, також завдаватися проклятій цілі. «Прокляття спустошення» може діяти лише на 1 ціль, і від одного чорнокнижника на одній цілі може діяти лише одне прокляття.",
        [1243356] = "Викопує скарб.",
        [1243845] = "Посилює ефект «Мокрого снігу» на $d.",
        [1243846] = "Посилює ефект «Пилової бурі» на $d.",
        [1243847] = "Посилює ефект «Спекотної жарини» на $d.",
        [1243960] = "Прикликає Век’зола.",
        [1243969] = "$?pc142418[Additionally, experience gained from kills is increased by $s1%.][]",
        [1243974] = "Завдає $S1 шкоди від вогню всім ворогам у межах $r ярдів.",
        [1244245] = "Відновлює $o1 здоров’я протягом $d.  Під час їжі потрібно залишатися сидячи. Якщо їсти щонайменше 10 секунд, ви насититеся й отримаєте $s1 витривалості та духу на $d. $?pc142418[Additionally, experience gained from kills is increased by $s1%.][]",
        [1244396] = "Вражає ворога блискавкою, що перескакує на іншого ворога поблизу. Закляття вражає до $x1 цілей, завдаючи кожній наступній цілі більшої шкоди від сил природи.\r\n",
        [1244416] = "Завдає $S2 фізичної шкоди всім гравцям у межах $r і приголомшує їх на $d.",
        [1244482] = "Ви озброєні імпровізованою й неохочою зброєю, що збільшує завдану шкоду на $S3% і зменшує отримувану шкоду на $S2%.\r\n",
        [1244484] = "Завдає $15578s1 фізичної шкоди всім гравцям у межах $15578d1 ярдів. Також накладає ауру, що зменшує швидкість руху на $s2 протягом $d2.",
        [1244493] = "Поглинає незвичайні сили Клоберта, змінюючи певні здібності.",
        [1244625] = "Висмоктує магію з розлому лей-лінії.",
        [1244863] = "Миттєво відновлює $s1 здоров’я, але з часом ви також отримуєте шкоду в розмірі $s2% від цієї величини.\r\n\r\nСимптоми цього ефекту можуть проявитися як отрута тривалістю $1231579d або хвороба тривалістю $1231580d.",
        [1244864] = "Миттєво відновлює $s1 здоров’я, але з часом ви також отримуєте шкоду в розмірі $s2% від цієї величини.\r\n\r\nСимптоми цього ефекту можуть проявитися як отрута тривалістю $1231579d або хвороба тривалістю $1231580d.",
        [1244865] = "Миттєво відновлює $s1 здоров’я, але з часом ви також отримуєте шкоду в розмірі $s2% від цієї величини.\r\n\r\nСимптоми цього ефекту можуть проявитися як отрута тривалістю $1231579d або хвороба тривалістю $1231580d.",
        [1244866] = "Миттєво відновлює $s1 здоров’я, але з часом ви також отримуєте шкоду в розмірі $s2% від цієї величини.\r\n\r\nСимптоми цього ефекту можуть проявитися як отрута тривалістю $1231579d або хвороба тривалістю $1231580d.",
        [1244867] = "Миттєво відновлює $s1 здоров’я, але з часом ви також отримуєте шкоду в розмірі $s2% від цієї величини.\r\n\r\nСимптоми цього ефекту можуть проявитися як отрута тривалістю $1231579d або хвороба тривалістю $1231580d.",
        [1244896] = "Завдає $S1 шкоди від вогню всім гравцям у межах $rad% ярдів.",
        [1244951] = "Зцілює ціль на 100% її максимального здоров’я.",
        [1245095] = "Поглинає незвичайні сили Клоберта, змінюючи певні здібності.",
        [1245119] = "Зменшує завдану шкоду на $s1% протягом $d.\r\n",
        [1245130] = "Завдає шкоди від вогню кожні $p протягом $d усім гравцям у межах $rad# ярдів.",
        [1245154] = "Видає могутній рев, приголомшуючи всіх гравців у межах $R1 на $d. ",
        [1245158] = "Намагається отримати інформацію про цільовий предмет. DNT",
        [1245164] = "Спричиняє кровотечу цілі, завдаючи $s1 фізичної шкоди кожні $t2 с протягом $d.",
        [1245249] = "Збільшує фізичну шкоду на $s1 протягом $d.",
        [1245320] = "Розділяє 1 купку дивного пилу на $s1 частинок магії.",
        [1245338] = "Прикликає двох духовних вовків.",
        [1245340] = "$@spelldesc<1245338>",
        [1245608] = "Збільшує вашу навичку гірництва на $m1. Не може підвищити навичку гірництва понад $m2. Ви вивчите гірництво, якщо ще не навчені й не знаєте двох інших професій.",
        [1245609] = "Збільшує вашу навичку травництва на $m1. Не може підвищити навичку травництва понад $m2. Ви вивчите травництво, якщо ще не навчені й не знаєте двох інших професій.",
        [1245610] = "Збільшує вашу навичку зняття шкур на $m1. Не може підвищити навичку зняття шкур понад $m2. Ви вивчите зняття шкур, якщо ще не навчені й не знаєте двох інших професій.\r\n",
        [1245705] = "Клацніть правою кнопкою, щоб прикликати або відкликати Мінімуса Тентакулуса. Мінімус Тентакулус полюбляє пожирати інших крихітних істот, щоб поглинати їхню силу.",
        [1245883] = "Приголомшує ворога, не даючи йому рухатися або діяти протягом $d. Також знімає з ураженого ворога один випадковий корисний ефект.",
        [1245940] = "Збільшує швидкість на $S1%. ",
        [1245956] = "Завдає поточній цілі $S1 шкоди від вогню.",
        [1246026] = "Допомагає зціленню та росту пишної рослинності.",
        [1246031] = "Показує на вашій мапі сліди кобольдів поблизу.",
        [1246362] = "Накладає ауру, через яку гравці вибухають після завершення ефекту, завдаючи $1246364s1 шкоди від тіні всім гравцям поблизу та залишаючи небезпечну калюжу.",
        [1246364] = "Завдає $S1 шкоди від тіні всім гравцям поблизу та залишає небезпечну калюжу тіні.",
        [1246367] = "Завдає $S1 шкоди від тіні кожні $t1 с.",
        [1246453] = "Змушує гравців іти до місця перебування заклинача.",
        [1246456] = "$@spelldesc<1246453>",
        [1247168] = "Прочитайте етикетку, щоб визначити вантаж.",
        [1247169] = "Несприйнятливість до шкоди з усіх джерел.",
        [1247237] = "Магія нечестивих тотемів захищає Невільний Дух, зменшуючи шкоду на $S1%.",
        [1247252] = "Очищає тотем, роблячи його вразливим і завдаючи значної шкоди протягом часу.\r\n",
        [1247426] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\n- $M3 мироцвіту\n- $M4 срібнолисту\n- $M5 земляного кореня\n- $M6 магокоролівської крові\n- $M7 гострошипу|r",
